### app/blog/[id]/page.tsx
import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import BackButton from './BackButton'
import { getPost, getPostComments, getPosts } from '@/lib/posts'
import type { Post } from '@/types/posts'

interface BlogPostPageProps {
  params: Promise<{ id: string }>
}

export const revalidate = 300

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts = await getPosts(10, {
    next: { revalidate },
  })

  return posts.map((post) => ({ id: String(post.id) }))
}

async function getPostById(id: string): Promise<Post | null> {
  try {
    return await getPost(id, { next: { revalidate } })
  } catch {
    return null
  }
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const post = await getPostById(id)

  if (!post) {
    return {
      title: 'Post Not Found',
    }
  }

  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({
  params,
}: BlogPostPageProps): Promise<JSX.Element> {
  const { id } = await params

  try {
    const [post, comments] = await Promise.all([
      getPost(id, { next: { revalidate } }),
      getPostComments(id, { next: { revalidate } }),
    ])

    return (
      <article>
        <BackButton />

        <h1>{post.title}</h1>
        <p>{post.body}</p>

        <h2>Comments ({comments.length})</h2>
        <div className="comments">
          {comments.map((comment) => (
            <div key={comment.id} className="comment">
              <h3>{comment.name}</h3>
              <p>{comment.body}</p>
              <small>By: {comment.email}</small>
            </div>
          ))}
        </div>
      </article>
    )
  } catch {
    notFound()
  }
}

