### app/page.tsx
import Link from 'next/link'
import { headers } from 'next/headers'
import type { Metadata } from 'next'
import { getPosts } from '@/lib/posts'

export const dynamic = 'force-dynamic'

export const metadata: Metadata = {
  title: 'Home',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

export default async function HomePage(): Promise<JSX.Element> {
  const headersList = await headers()
  const userAgent = headersList.get('user-agent') ?? ''
  const posts = await getPosts(5, { cache: 'no-store' })
  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <Link href="/blog" className="button-link">
        View All Posts
      </Link>
    </div>
  )
}

### components/AppProvider.tsx
'use client'

import {
  createContext,
  useContext,
  useMemo,
  useState,
  type Dispatch,
  type ReactNode,
  type SetStateAction,
} from 'react'

type Theme = 'light' | 'dark'

interface AppContextValue {
  theme: Theme
  setTheme: Dispatch<SetStateAction<Theme>>
}

const AppContext = createContext<AppContextValue | null>(null)

interface AppProviderProps {
  children: ReactNode
}

export function AppProvider({ children }: AppProviderProps): JSX.Element {
  const [theme, setTheme] = useState<Theme>('light')
  const value = useMemo(() => ({ theme, setTheme }), [theme])

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>
}

export function useAppContext(): AppContextValue {
  const context = useContext(AppContext)

  if (!context) {
    throw new Error('useAppContext must be used within AppProvider')
  }

  return context
}

