import { NextResponse } from 'next/server'
import type { ApiPost } from '@/types/posts'

interface RouteContext {
  params: Promise<{ id: string }>
}

interface UpdatePostRequest {
  title?: string
  content?: string
}

interface DeletePostResponse {
  message: string
}

function toPostId(id: string): number {
  const parsed = Number.parseInt(id, 10)
  return Number.isNaN(parsed) ? 0 : parsed
}

export async function GET(
  _request: Request,
  context: RouteContext
): Promise<NextResponse<ApiPost>> {
  const { id } = await context.params

  const post: ApiPost = {
    id: toPostId(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post, { status: 200 })
}

export async function PUT(
  request: Request,
  context: RouteContext
): Promise<NextResponse<ApiPost>> {
  const { id } = await context.params
  const body = (await request.json()) as UpdatePostRequest

  const updatedPost: ApiPost = {
    id: toPostId(id),
    title: body.title || `Post ${id}`,
    content: body.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost, { status: 200 })
}

export async function DELETE(
  _request: Request,
  context: RouteContext
): Promise<NextResponse<DeletePostResponse>> {
  const { id } = await context.params

  return NextResponse.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  )
}

