import type { Comment, Post } from '@/types/posts'

const JSON_PLACEHOLDER_BASE = 'https://jsonplaceholder.typicode.com'

async function fetchJson<T>(url: string, options?: RequestInit): Promise<T> {
  const response = await fetch(url, options)

  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status}`)
  }

  return (await response.json()) as T
}

export async function getPosts(
  limit?: number,
  options?: RequestInit
): Promise<Post[]> {
  const query = limit ? `?_limit=${limit}` : ''
  return fetchJson<Post[]>(`${JSON_PLACEHOLDER_BASE}/posts${query}`, options)
}

export async function getPost(id: string, options?: RequestInit): Promise<Post> {
  return fetchJson<Post>(`${JSON_PLACEHOLDER_BASE}/posts/${id}`, options)
}

export async function getPostComments(
  id: string,
  options?: RequestInit
): Promise<Comment[]> {
  return fetchJson<Comment[]>(
    `${JSON_PLACEHOLDER_BASE}/posts/${id}/comments`,
    options
  )
}

