     1	import { NextResponse } from 'next/server'
     2	import type { ApiPost } from '@/types/posts'
     3	
     4	interface RouteContext {
     5	  params: Promise<{ id: string }>
     6	}
     7	
     8	interface UpdatePostRequest {
     9	  title?: string
    10	  content?: string
    11	}
    12	
    13	interface DeletePostResponse {
    14	  message: string
    15	}
    16	
    17	function toPostId(id: string): number {
    18	  const parsed = Number.parseInt(id, 10)
    19	  return Number.isNaN(parsed) ? 0 : parsed
    20	}
    21	
    22	export async function GET(
    23	  _request: Request,
    24	  context: RouteContext
    25	): Promise<NextResponse<ApiPost>> {
    26	  const { id } = await context.params
    27	
    28	  const post: ApiPost = {
    29	    id: toPostId(id),
    30	    title: `Post ${id}`,
    31	    content: `This is the content for post ${id}`,
    32	    createdAt: new Date().toISOString(),
    33	  }
    34	
    35	  return NextResponse.json(post, { status: 200 })
    36	}
    37	
    38	export async function PUT(
    39	  request: Request,
    40	  context: RouteContext
    41	): Promise<NextResponse<ApiPost>> {
    42	  const { id } = await context.params
    43	  const body = (await request.json()) as UpdatePostRequest
    44	
    45	  const updatedPost: ApiPost = {
    46	    id: toPostId(id),
    47	    title: body.title || `Post ${id}`,
    48	    content: body.content || `Updated content for post ${id}`,
    49	    updatedAt: new Date().toISOString(),
    50	  }
    51	
    52	  return NextResponse.json(updatedPost, { status: 200 })
    53	}
    54	
    55	export async function DELETE(
    56	  _request: Request,
    57	  context: RouteContext
    58	): Promise<NextResponse<DeletePostResponse>> {
    59	  const { id } = await context.params
    60	
    61	  return NextResponse.json(
    62	    { message: `Post ${id} deleted successfully` },
    63	    { status: 200 }
    64	  )
    65	}
