     1	'use client'
     2	
     3	import {
     4	  createContext,
     5	  useContext,
     6	  useMemo,
     7	  useState,
     8	  type Dispatch,
     9	  type JSX,
    10	  type ReactNode,
    11	  type SetStateAction,
    12	} from 'react'
    13	
    14	type Theme = 'light' | 'dark'
    15	
    16	interface AppContextValue {
    17	  theme: Theme
    18	  setTheme: Dispatch<SetStateAction<Theme>>
    19	}
    20	
    21	const AppContext = createContext<AppContextValue | null>(null)
    22	
    23	interface AppProviderProps {
    24	  children: ReactNode
    25	}
    26	
    27	export function AppProvider({ children }: AppProviderProps): JSX.Element {
    28	  const [theme, setTheme] = useState<Theme>('light')
    29	  const value = useMemo(() => ({ theme, setTheme }), [theme])
    30	
    31	  return <AppContext.Provider value={value}>{children}</AppContext.Provider>
    32	}
    33	
    34	export function useAppContext(): AppContextValue {
    35	  const context = useContext(AppContext)
    36	
    37	  if (!context) {
    38	    throw new Error('useAppContext must be used within AppProvider')
    39	  }
    40	
    41	  return context
    42	}
