     1	import type { Comment, Post } from '@/types/posts'
     2	
     3	const JSON_PLACEHOLDER_BASE = 'https://jsonplaceholder.typicode.com'
     4	
     5	async function fetchJson<T>(url: string, options?: RequestInit): Promise<T> {
     6	  const response = await fetch(url, options)
     7	
     8	  if (!response.ok) {
     9	    throw new Error(`Request failed with status ${response.status}`)
    10	  }
    11	
    12	  return (await response.json()) as T
    13	}
    14	
    15	export async function getPosts(
    16	  limit?: number,
    17	  options?: RequestInit
    18	): Promise<Post[]> {
    19	  const query = limit ? `?_limit=${limit}` : ''
    20	  return fetchJson<Post[]>(`${JSON_PLACEHOLDER_BASE}/posts${query}`, options)
    21	}
    22	
    23	export async function getPost(id: string, options?: RequestInit): Promise<Post> {
    24	  return fetchJson<Post>(`${JSON_PLACEHOLDER_BASE}/posts/${id}`, options)
    25	}
    26	
    27	export async function getPostComments(
    28	  id: string,
    29	  options?: RequestInit
    30	): Promise<Comment[]> {
    31	  return fetchJson<Comment[]>(
    32	    `${JSON_PLACEHOLDER_BASE}/posts/${id}/comments`,
    33	    options
    34	  )
    35	}
